$ErrorActionPreference = 'Stop'
# AEGIS NIDS - G40 Gate F Enforcement Deployment
# Generated by generate_g40.py
# Purpose: add manual enforcement commands to aegisctl (v4).
#          This is the FINAL gate in the RUN_FIRST -> VERIFY -> CONNECT
#          -> CONTROL strategy.
#
# Gate F (Enforcement) adds 3 command groups to aegisctl:
#
#   aegisctl block add --ip IP [--duration SECS] [--reason TEXT]
#     Block an IP address. Saves to logs/blocked_ips.json and signals
#     core to apply via WFP IOCTL (SIGUSR1 on POSIX, file-watch on Windows).
#
#   aegisctl block remove --ip IP
#     Remove an IP from the block list.
#
#   aegisctl block list
#     List all blocked IPs with timestamps and durations.
#
#   aegisctl block clear
#     Clear all blocked IPs.
#
#   aegisctl enforce status
#     Show PEP (Policy Enforcement Point) status: enabled, mode, blocked count,
#     shield DLL presence.
#
#   aegisctl enforce enable
#     Enable PEP enforcement (Drop/Block rules will be enforced).
#
#   aegisctl enforce disable
#     Disable PEP enforcement (fail-open mode -- alerts only, no blocks).
#     WARNING: use with caution in production.
#
#   aegisctl enforce push --policy FILE
#     Push a policy file to the PEP (copies to config/Rules.json, then
#     run 'aegisctl policy reload' to activate).
#
#   aegisctl quarantine add --ip IP [--reason TEXT]
#     Quarantine an IP (stricter than block -- adds to both quarantine list
#     and block list, logs the event).
#
#   aegisctl quarantine remove --ip IP
#     Remove an IP from quarantine (also unblocks it).
#
#   aegisctl quarantine list
#     List all quarantined IPs.
#
# State files:
#   logs/blocked_ips.json     -- list of blocked IPs
#   logs/quarantine.json      -- list of quarantined IPs
#   logs/runtime/pep_state.json -- PEP enabled/disabled state
#
# After deployment:
#   1. python scripts\aegisctl.py enforce status
#   2. python scripts\aegisctl.py block add --ip 1.2.3.4 --reason "Test"
#   3. python scripts\aegisctl.py block list
#   4. python scripts\aegisctl.py quarantine add --ip 5.6.7.8
#   5. python scripts\aegisctl.py quarantine list
#   6. python scripts\aegisctl.py enforce disable  (test fail-open)
#   7. python scripts\aegisctl.py enforce enable   (re-enable)
#   8. python -m pytest tests/runtime/test_gate_f.py -v
#
# Conventions:
#   - Pure ASCII content (UTF-8 BOM at start of this file only)
#   - No CRCRLF
#   - Each file written via [System.IO.File]::WriteAllText (UTF-8 no BOM)

$repoRoot = (Get-Location).Path
Write-Host ""
Write-Host "=== AEGIS NIDS - G40 Gate F Enforcement Deployment ===" -ForegroundColor Cyan
Write-Host "Repo root: $repoRoot" -ForegroundColor DarkGray
Write-Host ""

# Pre-flight: verify we are at the repo root
$markerFiles = @('build.zig', 'CMakeLists.txt', 'Cargo.toml', 'go.mod')
foreach ($m in $markerFiles) {
    if (-not (Test-Path (Join-Path $repoRoot $m))) {
        Write-Warning "marker file $m not found; you may not be at the AEGIS repo root."
    }
}

# Create directories
$dirs = @('scripts', 'tests/runtime', 'config', 'logs/runtime', 'logs')
foreach ($d in $dirs) {
    $p = Join-Path $repoRoot $d
    if (-not (Test-Path $p)) {
        New-Item -ItemType Directory -Path $p -Force | Out-Null
        Write-Host "  [+] created $d" -ForegroundColor Green
    } else {
        Write-Host "  [.] exists  $d" -ForegroundColor DarkGray
    }
}
Write-Host ""

