$utf8_tests_runtime_test_gate_f_py  = [System.Text.Encoding]::UTF8.GetString($bytes_tests_runtime_test_gate_f_py)
$out_tests_runtime_test_gate_f_py   = Join-Path $repoRoot 'tests/runtime/test_gate_f.py'
[System.IO.File]::WriteAllText($out_tests_runtime_test_gate_f_py, $utf8_tests_runtime_test_gate_f_py, (New-Object System.Text.UTF8Encoding($false)))
$size_tests_runtime_test_gate_f_py  = (Get-Item $out_tests_runtime_test_gate_f_py).Length
Write-Host ("  [2] tests/runtime/test_gate_f.py bytes=" + $size_tests_runtime_test_gate_f_py) -ForegroundColor Yellow


# ------------------------------------------------------------------ #
# Final verification                                                  #
# ------------------------------------------------------------------ #
Write-Host ""
Write-Host "=== Deployment complete ===" -ForegroundColor Cyan
Write-Host ""
Write-Host "Files written:"
$files = @(
    'scripts/aegisctl.py',
    'tests/runtime/test_gate_f.py'
)
$ok = 0
$missing = 0
foreach ($f in $files) {
    $p = Join-Path $repoRoot $f
    if (Test-Path $p) {
        $sz = (Get-Item $p).Length
        Write-Host ("  OK   " + $f + " (" + $sz + " bytes)") -ForegroundColor Green
        $ok++
    } else {
        Write-Host ("  MISS " + $f) -ForegroundColor Red
        $missing++
    }
}
Write-Host ""
if ($missing -eq 0) {
    Write-Host ("Total: " + $ok + " OK, 0 missing") -ForegroundColor Green
} else {
    Write-Host ("Total: " + $ok + " OK, " + $missing + " missing") -ForegroundColor Red
    exit 1
}
Write-Host ""

# ------------------------------------------------------------------ #
# Next steps                                                          #
# ------------------------------------------------------------------ #
Write-Host "Next steps:" -ForegroundColor Cyan
Write-Host "  1. Show PEP enforcement status:"
Write-Host "       python scripts\aegisctl.py enforce status" -ForegroundColor Yellow
Write-Host "  2. Block an IP:"
Write-Host "       python scripts\aegisctl.py block add --ip 1.2.3.4 --reason 'Suspicious'" -ForegroundColor Yellow
Write-Host "  3. List blocked IPs:"
Write-Host "       python scripts\aegisctl.py block list" -ForegroundColor Yellow
Write-Host "  4. Quarantine an IP (stricter than block):"
Write-Host "       python scripts\aegisctl.py quarantine add --ip 5.6.7.8 --reason 'Compromised'" -ForegroundColor Yellow
Write-Host "  5. List quarantined IPs:"
Write-Host "       python scripts\aegisctl.py quarantine list" -ForegroundColor Yellow
Write-Host "  6. Disable enforcement (fail-open, alerts only):"
Write-Host "       python scripts\aegisctl.py enforce disable" -ForegroundColor Yellow
Write-Host "  7. Re-enable enforcement:"
Write-Host "       python scripts\aegisctl.py enforce enable" -ForegroundColor Yellow
Write-Host "  8. Run Gate F test suite (30 tests):"
Write-Host "       python -m pytest tests/runtime/test_gate_f.py -v" -ForegroundColor Yellow
Write-Host "  9. Run full runtime contract suite (241 tests):"
Write-Host "       python -m pytest tests/runtime/ -v" -ForegroundColor Yellow
